contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit an amount, attempt withdrawAll twice, and assert the general invariant described above.
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // perform deposit
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // observe balances immediately after deposit
        uint tester_balance_after_deposit = address(this).balance;
        uint c_balance_after_deposit = address(c).balance;

        // first withdrawAll attempt (top-level state-changing call)
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // observe balances after first withdraw
        uint tester_balance_after_first = address(this).balance;
        uint c_balance_after_first = address(c).balance;

        // second withdrawAll attempt (top-level state-changing call)
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // observe balances after second withdraw
        uint tester_balance_after_second = address(this).balance;
        uint c_balance_after_second = address(c).balance;

        // Exactly one assert as required: either first call reverted and balances unchanged thereafter,
        // or first call succeeded and transferred exactly depositAmount, and second call leaves balances unchanged.
        assert(
            (firstReverted
                && tester_balance_after_first == tester_balance_after_deposit
                && c_balance_after_first == c_balance_after_deposit
                && tester_balance_after_second == tester_balance_after_deposit
                && c_balance_after_second == c_balance_after_deposit)
            || (!firstReverted
                && tester_balance_after_first == tester_balance_after_deposit + depositAmount
                && c_balance_after_first + depositAmount == c_balance_after_deposit
                && tester_balance_after_second == tester_balance_after_first
                && c_balance_after_second == c_balance_after_first)
        );
    }

    receive() external payable { }
}

