// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint tester_balance_after_deposit = address(this).balance;
        uint c_balance_after_deposit = address(c).balance;
        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint tester_balance_after_first = address(this).balance;
        uint c_balance_after_first = address(c).balance;
        bool secondReverted;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint tester_balance_after_second = address(this).balance;
        uint c_balance_after_second = address(c).balance;
        assertTrue((firstReverted
                && tester_balance_after_first == tester_balance_after_deposit
                && c_balance_after_first == c_balance_after_deposit
                && tester_balance_after_second == tester_balance_after_deposit
                && c_balance_after_second == c_balance_after_deposit)
            || (!firstReverted
                && tester_balance_after_first == tester_balance_after_deposit + depositAmount
                && c_balance_after_first + depositAmount == c_balance_after_deposit
                && tester_balance_after_second == tester_balance_after_first
                && c_balance_after_second == c_balance_after_first));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable { }
}
